type UpdateServerMetaParams struct {
	Name        *string
	Description *string
	Status      *string
	OrgID       *uuid.UUID
	ID          uuid.UUID
	IfUpdatedAt *time.Time
}

func (q *Queries) UpdateServerMeta(ctx context.Context, arg UpdateServerMetaParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateServerMeta,
		arg.Name,
		arg.Description,
		arg.Status,
		arg.OrgID,
		arg.ID,
		arg.IfUpdatedAt,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
